@@ -0,0 +1,35 @@
+// Sites: the kitchens Larder serves. Every location belongs to one site;
+// batches belong to the site of their location. Items, suppliers, recipes and
+// dishes are shared by all sites.
+import { AppError } from "../errors.js";
+
+/** The site used when a request names none. */
+export const MAIN_SITE = "main";
+
+/** Every site, in list order. */
+export function listSites(store) {
+  return [...(store.data.sites ?? [])];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The location with `id` if it belongs to `site`, else null. */
+export function siteLocation(store, site, id) {
+  return store.data.locations.find((l) => l.id === id && l.site === site) ?? null;
+}
+
+/** Ids of the locations of a site. */
+export function siteLocationIds(store, site) {
+  return new Set(store.data.locations.filter((l) => l.site === site).map((l) => l.id));
+}
+
+/** The batches stored at a site's locations. */
+export function siteBatches(store, site) {
+  const here = siteLocationIds(store, site);
+  return store.data.batches.filter((b) => here.has(b.location));
+}
